# Shared helpers for infra/fleet/bootstrap/<role>.sh. Sourced, never run directly.
# Pins come from packages/machine/toolchains.lock.toml (generated by scripts/toolchains-lock.ts).
# Every step is idempotent: it checks the installed version first and only acts on drift.
set -eu

: "${LOCK:?LOCK=path to toolchains.lock.toml}"
ARCH=$(uname -m)
case "$ARCH" in x86_64) PLAT=linux-x86_64 ;; aarch64) PLAT=linux-aarch64 ;; *) echo "unsupported arch $ARCH" >&2; exit 1 ;; esac
SUDO=""; [ "$(id -u)" = 0 ] || SUDO="sudo"
BIN=/usr/local/bin
log() { printf '[bootstrap] %s\n' "$*"; }

# lock_get <tool> <key>: scalar value from [toolchain."<tool>"].
lock_get() {
  awk -v sect="[toolchain.\"$1\"]" -v key="$2" '
    $0 == sect { in_s = 1; next }
    /^\[/ { in_s = 0 }
    in_s && $1 == key && $2 == "=" { sub(/^[^=]*= */, ""); gsub(/^"|"$/, ""); print; exit }' "$LOCK"
}
# lock_art <tool> <field url|sha256|sha512>: field of this host platform's artifact.
lock_art() {
  awk -v sect="[toolchain.\"$1\"]" -v plat="$PLAT" -v f="$2" '
    $0 == sect { in_s = 1; next }
    /^\[/ { in_s = 0 }
    in_s && $1 == plat { if (match($0, f " = \"[^\"]*\"")) { s = substr($0, RSTART, RLENGTH); sub(/^[^"]*"/, "", s); sub(/"$/, "", s); print s; exit } }' "$LOCK"
}

# fetch <tool> <dest>: download this platform's artifact and verify its checksum (sha256 or sha512).
fetch() {
  url=$(lock_art "$1" url); [ -n "$url" ] || { echo "no $PLAT artifact for $1" >&2; return 1; }
  # IPv4 fallback: fr1 gets 404 from dl.google.com over IPv6 (seen 2026-11-13 on go1.27.4).
  curl -fsSL --retry 3 -o "$2" "$url" || curl -4 -fsSL --retry 3 -o "$2" "$url"
  if sum=$(lock_art "$1" sha256) && [ -n "$sum" ]; then echo "$sum  $2" | sha256sum -c --quiet -
  elif sum=$(lock_art "$1" sha512) && [ -n "$sum" ]; then echo "$sum  $2" | sha512sum -c --quiet -
  else echo "no checksum for $1" >&2; return 1; fi
}

# has_version <cmd...> <want>: true when the command output contains the pinned version.
has_version() {
  want=$1; shift
  command -v "$1" >/dev/null 2>&1 && "$@" 2>&1 | head -3 | grep -qF -- "$want"
}

# install_archive_bin <tool> <binary-name-in-archive> [dest-name]: tar/zip/raw release asset -> $BIN.
install_archive_bin() {
  tool=$1; inner=$2; dest=${3:-$2}; tmp=$(mktemp -d)
  url=$(lock_art "$tool" url)
  fetch "$tool" "$tmp/a"
  case "$url" in
    *.zip) (cd "$tmp" && python3 -c 'import sys,zipfile; zipfile.ZipFile(sys.argv[1]).extractall(".")' a) ;;
    *.tar.gz|*.tgz) tar -xzf "$tmp/a" -C "$tmp" ;;
    *.tar.xz) tar -xJf "$tmp/a" -C "$tmp" ;;
    *) cp "$tmp/a" "$tmp/$inner" ;;
  esac
  f=$(find "$tmp" -type f -name "$inner" | head -1)
  $SUDO install -m 0755 "$f" "$BIN/$dest"
  rm -rf "$tmp"
  # Purge stale per-user copies that would shadow the pinned one on PATH.
  for old in "$HOME/.cargo/bin/$dest" "$HOME/.local/bin/$dest"; do [ -e "$old" ] && rm -f "$old" && log "purged $old"; done
  log "$tool -> $BIN/$dest"
}

# Rust: pinned nightly, components and targets, for user $1 (rustup must exist).
rust_pinned() {
  tc=$(lock_get rust version)
  as_user=$1
  run() { if [ "$as_user" = "$(id -un)" ]; then sh -c "$1"; else $SUDO -iu "$as_user" sh -c "$1"; fi; }
  run "rustup toolchain install $tc --profile minimal -c rustfmt,clippy,rust-src,rust-analyzer,llvm-tools -t x86_64-unknown-linux-musl,aarch64-unknown-linux-musl,aarch64-unknown-linux-gnu,wasm32-unknown-unknown,wasm32-wasip2 >/dev/null && rustc +$tc -V"
}

# Bun at the pinned version (official zip, checksum from the lock).
bun_pinned() {
  want=$(lock_get bun version)
  has_version "$want" bun --version && { log "bun $want ok"; return; }
  install_archive_bin bun bun
}

# .NET SDK into /opt/dotnet (tarball, sha512 from Microsoft release metadata).
dotnet_pinned() {
  want=$(lock_get dotnet-sdk version)
  if [ -x /opt/dotnet/dotnet ] && /opt/dotnet/dotnet --list-sdks | grep -q "^$want "; then log "dotnet $want ok"; else
    tmp=$(mktemp -d); fetch dotnet-sdk "$tmp/sdk.tgz"
    $SUDO mkdir -p /opt/dotnet && $SUDO tar -xzf "$tmp/sdk.tgz" -C /opt/dotnet && rm -rf "$tmp"
    log "dotnet $want -> /opt/dotnet"
  fi
  $SUDO ln -sf /opt/dotnet/dotnet "$BIN/dotnet"
  printf 'export DOTNET_ROOT=/opt/dotnet\nexport DOTNET_CLI_TELEMETRY_OPTOUT=1\n' | $SUDO tee /etc/profile.d/dotnet.sh >/dev/null
}

# Zig tree into /opt/zig-<ver>, linked into $BIN.
zig_pinned() {
  want=$(lock_get zig version)
  has_version "$want" zig version && { log "zig $want ok"; return; }
  tmp=$(mktemp -d); fetch zig "$tmp/zig.tar.xz"
  $SUDO mkdir -p "/opt/zig-$want" && $SUDO tar -xJf "$tmp/zig.tar.xz" -C "/opt/zig-$want" --strip-components=1 && rm -rf "$tmp"
  $SUDO ln -sf "/opt/zig-$want/zig" "$BIN/zig"
  log "zig $want -> /opt/zig-$want"
}

go_pinned() {
  want=$(lock_get go version)
  has_version "go$want" go version && { log "go $want ok"; return; }
  [ -x /usr/local/go/bin/go ] && /usr/local/go/bin/go version | grep -qF "go$want" || {
    tmp=$(mktemp -d); fetch go "$tmp/go.tgz"
    $SUDO rm -rf /usr/local/go && $SUDO tar -xzf "$tmp/go.tgz" -C /usr/local && rm -rf "$tmp"
  }
  $SUDO ln -sf /usr/local/go/bin/go "$BIN/go"; $SUDO ln -sf /usr/local/go/bin/gofmt "$BIN/gofmt"
  log "go $want -> /usr/local/go"
}

# Docker: engine enabled, buildx multi-arch builder (docker-container driver + binfmt for arm64).
docker_runtime() {
  $SUDO systemctl enable --now docker >/dev/null 2>&1 || $SUDO systemctl start docker
  docker info --format '{{.ServerVersion}}' >/dev/null
}
docker_multiarch() {
  docker_runtime
  docker run --privileged --rm tonistiigi/binfmt:qemu-v10.1.3 --install arm64 >/dev/null 2>&1 || docker run --privileged --rm tonistiigi/binfmt --install arm64 >/dev/null
  # BuildKit capped (BUILDKIT_CPUS, default 2; BUILDKIT_MEM, default 8g); builds go through infra/fleet/bin/heavy.sh.
  cpus=${BUILDKIT_CPUS:-2}; mem=${BUILDKIT_MEM:-8g}
  docker buildx inspect aphrody >/dev/null 2>&1 || docker buildx create --name aphrody --driver docker-container \
    --driver-opt network=host --driver-opt cpu-quota=$((cpus * 100000)) --driver-opt cpu-period=100000 --driver-opt memory="$mem" --bootstrap >/dev/null
  docker update --cpus "$cpus" --memory "$mem" --memory-swap "$mem" buildx_buildkit_aphrody0 >/dev/null 2>&1 || true
  for h in "$(dirname "$0")/heavy.sh" "$(dirname "$0")/../bin/heavy.sh"; do [ -f "$h" ] && $SUDO install -m 0755 "$h" "$BIN/aphrody-heavy" && break; done
  docker buildx inspect aphrody | grep -E '^Platforms' | head -1
}

# --- Agents (owner decision 2026-11-13, NHITL): user `agent` = full root through sudo, on every host. ---
# Claude Code refuses bypassPermissions as uid 0 without a sandbox, so agents run as `agent` and escalate
# with `sudo` (NOPASSWD: ALL, /etc/sudoers.d/aphrody-agent validated by visudo -cf), member of docker.
# Rollback: sudo rm /etc/sudoers.d/aphrody-agent
AGENT=${AGENTS_USER:-agent}
# Repo root of this bootstrap tree (role scripts live in infra/fleet/bootstrap/), independent of where LOCK is.
ROOT=$(cd "$(dirname "$0")/../../.." && pwd)
agent_user() {
  id "$AGENT" >/dev/null 2>&1 || { $SUDO useradd -m -s /bin/bash "$AGENT"; log "user $AGENT created"; }
  H=$(getent passwd "$AGENT" | cut -d: -f6)
  # Login keys = public keys of the bootstrap user (and root's), appended once.
  { cat "$HOME/.ssh/authorized_keys" 2>/dev/null; $SUDO cat /root/.ssh/authorized_keys 2>/dev/null; } |
    sudo -u "$AGENT" sh -c 'umask 077; mkdir -p "$1/.ssh"; touch "$1/.ssh/authorized_keys"; cat - "$1/.ssh/authorized_keys" | sort -u > "$1/.ssh/k" && mv "$1/.ssh/k" "$1/.ssh/authorized_keys"' _ "$H"
  getent group docker >/dev/null && $SUDO usermod -aG docker "$AGENT"
  t=$(mktemp); printf '# infra/fleet/bootstrap/common.sh agent_user (owner decision 2026-11-13)\n%s ALL=(ALL:ALL) NOPASSWD: ALL\n' "$AGENT" > "$t"
  $SUDO visudo -cf "$t" >/dev/null && $SUDO install -m 0440 -o root -g root "$t" /etc/sudoers.d/aphrody-agent; rm -f "$t"
  $SUDO visudo -c >/dev/null
  $SUDO loginctl enable-linger "$AGENT"
  $SUDO install -d -m 0755 -o "$AGENT" -g "$AGENT" /var/lib/aphrody-agents /var/lib/aphrody-agents/logs
  $SUDO chown -R "$AGENT:$AGENT" /var/lib/aphrody-agents
  sudo -u "$AGENT" sudo -n true && log "agent: sudo NOPASSWD ok, groups $(id -nG "$AGENT")"
}

# Runner (infra/agents/install.sh) as `agent`. On hosts whose login user is not root (fr1, fr2), the login
# user's CLI logins (OAuth files, never in git) and checkout seed the agent user once, then its own runner
# units are retired: one runner per host.
agent_runner() {
  H=$(getent passwd "$AGENT" | cut -d: -f6); me=$(id -un)
  if [ "$me" != "$AGENT" ] && [ "$me" != root ]; then
    for f in .claude/.credentials.json .codex/auth.json .config/gh/hosts.yml; do
      [ -f "$HOME/$f" ] && ! $SUDO test -f "$H/$f" &&
        sudo -u "$AGENT" sh -c 'umask 077; mkdir -p "$(dirname "$1")"; cat > "$1"' _ "$H/$f" < "$HOME/$f" && log "seeded $AGENT ~/$f"
    done
    if [ -d "$HOME/agents/src/.git" ] && ! $SUDO test -d "$H/agents/src/.git"; then
      $SUDO install -d -o "$AGENT" -g "$AGENT" "$H/agents"
      $SUDO cp -a "$HOME/agents/src" "$H/agents/src" && $SUDO chown -R "$AGENT:$AGENT" "$H/agents/src"
    fi
    systemctl --user disable --now aphrody-agents.service aphrody-agents-health.timer aphrody-agents-pull.timer >/dev/null 2>&1 || true
    rm -rf "$HOME"/.config/systemd/user/aphrody-agents*; systemctl --user daemon-reload 2>/dev/null || true
  fi
  root=$ROOT
  sudo -iu "$AGENT" sh -s < "$root/infra/agents/install.sh"
}

# Agent CLIs in full-access mode for interactive use too (the runner already passes the flags).
# Keys checked against the installed builds (2026-11-13): Claude Code 2.1.32x permissions.defaultMode +
# skipDangerousModePermissionPrompt; codex 0.16x approval_policy/sandbox_mode (values from `codex --help`);
# opencode 1.19 `permission` (action string). gemini-cli 0.68 ignores defaultApprovalMode=yolo from
# settings (flag --approval-mode yolo only) and pi has no permission gate: nothing to write for them.
agent_cli_fullaccess() {
  sudo -iu "$AGENT" sh -s <<'EOF'
set -eu
B=$(PATH="$HOME/.bun/bin:$HOME/.local/bin:/usr/local/bin:$PATH" command -v bun); "$B" -e '
const fs = require("fs"), p = require("path"), H = process.env.HOME;
const merge = (f, fn) => { fs.mkdirSync(p.dirname(f), { recursive: true });
  const j = fs.existsSync(f) ? JSON.parse(fs.readFileSync(f, "utf8")) : {}; fn(j);
  fs.writeFileSync(f, JSON.stringify(j, null, 2) + "\n", { mode: 0o600 }); };
merge(H + "/.claude/settings.json", j => { j.permissions = { ...(j.permissions ?? {}), defaultMode: "bypassPermissions" }; j.skipDangerousModePermissionPrompt = true; });
merge(H + "/.config/opencode/opencode.json", j => { j.$schema ??= "https://opencode.ai/config.json"; j.permission = "allow"; });'
c=$HOME/.codex/config.toml; mkdir -p "$HOME/.codex"; touch "$c"
sed -i '/^approval_policy *=/d;/^sandbox_mode *=/d' "$c"
{ printf 'approval_policy = "never"\nsandbox_mode = "danger-full-access"\n'; cat "$c"; } > "$c.new" && mv "$c.new" "$c"
EOF
  log "agent CLIs: full access (claude, codex, opencode)"
}
# Entry point called by every <role>.sh.
agents_cli() { agent_user; agent_runner; agent_cli_fullaccess; }

# --- Resilience (owner decision 2026-11-13, docs/infra/RESILIENCE.md): everything survives reboot/crash. ---
# Units, timers, linger, user units, compose restart policy and fstab nofail are driven by
# infra/fleet/bin/fleet-resilience.sh from infra/fleet/<host>/resilience.conf (`just fleet-resilience apply`);
# this adds what that file does not own: persistent bounded journald and the docker engine at boot.
# Rollback: rm /etc/systemd/journald.conf.d/10-aphrody.conf && systemctl restart systemd-journald
resilience() {
  $SUDO install -d /etc/systemd/journald.conf.d /var/log/journal
  printf '[Journal]\nStorage=persistent\nSystemMaxUse=%s\n' "${JOURNAL_MAX:-2G}" | $SUDO tee /etc/systemd/journald.conf.d/10-aphrody.conf >/dev/null
  $SUDO systemd-tmpfiles --create --prefix /var/log/journal >/dev/null 2>&1 || true
  # A later drop-in with Storage=volatile/auto (zz-vps-limits.conf on fr1) would win: Storage is set here only.
  for d in /etc/systemd/journald.conf.d/*.conf; do [ "$d" = /etc/systemd/journald.conf.d/10-aphrody.conf ] || $SUDO sed -i "/^Storage=/d" "$d"; done
  $SUDO systemctl restart systemd-journald && $SUDO journalctl --flush
  for u in containerd.service docker.socket docker.service; do systemctl cat "$u" >/dev/null 2>&1 && $SUDO systemctl enable "$u" >/dev/null 2>&1; done
  if [ -x /usr/local/bin/fleet-resilience.sh ] && [ -r /etc/fleet/resilience.conf ]; then $SUDO /usr/local/bin/fleet-resilience.sh apply | grep -v '^OK' || true; fi
}
# sysctl_serve: one tuning file for the serving hosts (prd, fr2), replacing older per-app drop-ins.
sysctl_serve() {
  root=$ROOT
  $SUDO install -m 0644 "$root/infra/fleet/sysctl/90-aphrody-serve.conf" /etc/sysctl.d/90-aphrody-serve.conf
  for old in 90-dbfr.conf 90-yolo-swappiness.conf 99-yolo-2026-perf.conf; do $SUDO rm -f "/etc/sysctl.d/$old"; done
  echo tcp_bbr | $SUDO tee /etc/modules-load.d/aphrody-bbr.conf >/dev/null; $SUDO modprobe tcp_bbr 2>/dev/null || true
  $SUDO install -d /etc/systemd/system.conf.d
  # Stop timeout 45 s (default 90 s): stuck login sessions held the prd reboot of 2026-11-13 for 4.5 min.
  printf '[Manager]\nDefaultLimitNOFILE=1048576\nDefaultTasksMax=infinity\nDefaultTimeoutStopSec=45s\n' | $SUDO tee /etc/systemd/system.conf.d/limits.conf >/dev/null
  $SUDO sysctl -q --system 2>&1 | grep -v '^\*' | head -3 || true
}

report() {
  for c in "$@"; do printf '  %-14s %s\n' "$c" "$( (command -v "$c" >/dev/null && case $c in go) go version ;; zig) zig version ;; caddy) caddy version ;; nginx) nginx -v ;; rustc) rustc +"$(lock_get rust version)" -V ;; *) "$c" --version ;; esac) 2>&1 | head -1 || echo MISSING)"; done
}

# role_mark <fr1|fr2|prd>: /etc/aphrody/role, read by aphrody-heavy (heavy jobs on fr1 only) and the audit.
role_mark() {
  $SUDO install -d /etc/aphrody; echo "$1" | $SUDO tee /etc/aphrody/role >/dev/null
  # aphrody-heavy on every host: runs the job on fr1, refuses elsewhere (exit 64).
  h=$ROOT/infra/fleet/bin/heavy.sh; if [ -f "$h" ]; then $SUDO install -m 0755 "$h" "$BIN/aphrody-heavy"; fi
}
